import{_ as o,o as a,c as n,a5 as p}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"这台电脑不满足 Windows 11 的最低要求解决方案","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["win系统问题"],"标签":["win11","win11安装","这台电脑不满足Windows 11 的最低要求"]},"headers":[],"relativePath":"md/win系统问题/这台电脑不满足 Windows 11 的最低要求解决方案.md","filePath":"md/win系统问题/这台电脑不满足 Windows 11 的最低要求解决方案.md"}'),s={name:"md/win系统问题/这台电脑不满足 Windows 11 的最低要求解决方案.md"};function e(r,t,w,g,c,l){return a(),n("div",null,[...t[0]||(t[0]=[p('<p>要安装 Windows 11，请从官方网站 microsoft.com 下载 ISO 镜像。</p><p>安装此操作系统，已引入了一些额外的要求，这在某些情况下可能会阻止安装，本教程解决这台电脑不满足 Windows 11 的最低要求解决方案，可以在任意电脑中正常进行安装win11。</p><p>在本指南中，我们将向您展示如何在使用官方分发版和文档的情况下禁用这些要求。</p><h3 id="跳过微软登录验证" tabindex="-1">跳过微软登录验证 <a class="header-anchor" href="#跳过微软登录验证" aria-label="Permalink to &quot;跳过微软登录验证&quot;">​</a></h3><p>安装win11时不要联网即可跳过</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251031232953176192459380899.png" alt=""></p><h3 id="进入安装界面后-点击疫情版本的安装程序" tabindex="-1">进入安装界面后，点击疫情版本的安装程序 <a class="header-anchor" href="#进入安装界面后-点击疫情版本的安装程序" aria-label="Permalink to &quot;进入安装界面后，点击疫情版本的安装程序&quot;">​</a></h3><p>如下图所示：</p><h3 id="看到这一步后-执行下一步-看到这一步后执行下方步骤-1-打开注册表" tabindex="-1"><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101150234176198055419605.jpg" alt=""> 看到这一步后，执行下一步 <img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251031233810176192509032706.jpg" alt=""> 看到这一步后执行下方步骤 <img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251031233859176192513915826.jpg" alt=""> 1. 打开注册表 <a class="header-anchor" href="#看到这一步后-执行下一步-看到这一步后执行下方步骤-1-打开注册表" aria-label="Permalink to &quot;![](https://www.softbangong.com/wp-content/uploads/2026/04/20251101150234176198055419605.jpg) 看到这一步后，执行下一步 ![](https://www.softbangong.com/wp-content/uploads/2026/04/20251031233810176192509032706.jpg) 看到这一步后执行下方步骤 ![](https://www.softbangong.com/wp-content/uploads/2026/04/20251031233859176192513915826.jpg) 1. 打开注册表&quot;">​</a></h3><p>1、按下 Shift + F10 打开控制台并启动注册表编辑器</p><p>2、在打开的控制台中，输入 <strong>regedit</strong>，然后按 <strong>Enter</strong></p><p>3、找到并展开** HKEY_LOCAL_MACHINE\\SYSTEM\\Setup**</p><p>鼠标右键在<strong>Setup</strong>上点击，然后点击新建项，命名为<strong>labConfig</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101150536176198073631636.jpg" alt=""></p><h3 id="_2-创建必要的参数以解除限制" tabindex="-1">2.创建必要的参数以解除限制 <a class="header-anchor" href="#_2-创建必要的参数以解除限制" aria-label="Permalink to &quot;2.创建必要的参数以解除限制&quot;">​</a></h3><p><strong>添加值为 1 的 DWORD 参数如下所示：</strong></p><p>BypassCPUCheck – 针对不兼容的处理器；</p><p>BypassTPMCheck – 无 TPM 2.0 芯片；</p><p>BypassRAMCheck – 不检查最低 RAM 要求；</p><p>BypassSecureBootCheck – 使用 Legacy BIOS（或禁用 Secure Boot 的 UEFI）；</p><p>BypassStorageCheck – 不检查系统盘大小。</p><p><strong>选择我们创建的 labConfig 分支文件夹，在右侧空白处鼠标右键点击创建DWORD参数和值</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101150729176198084941512.jpg" alt=""></p><p>对上边添加的每一个** DWORD（32位）**的值进行修改，选中后鼠标右键点击修改，将数值数据修改为1</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151010176198101047912.jpg" alt=""></p><p><strong>然后关闭注册表窗口和命令行窗口，如下所示的两个窗口全部关闭，</strong></p><h3 id="保持主安装窗口打开。" tabindex="-1">保持主安装窗口打开。 <a class="header-anchor" href="#保持主安装窗口打开。" aria-label="Permalink to &quot;保持主安装窗口打开。&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151234176198115463379.jpg" alt=""></p><h3 id="看到这个界面" tabindex="-1">看到这个界面 <a class="header-anchor" href="#看到这个界面" aria-label="Permalink to &quot;看到这个界面&quot;">​</a></h3><p>点击现在安装</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251031233859176192513915826.jpg" alt=""></p><p>执行下一步</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151439176198127988929.jpg" alt=""></p><h3 id="看到这个界面-1" tabindex="-1">看到这个界面 <a class="header-anchor" href="#看到这个界面-1" aria-label="Permalink to &quot;看到这个界面&quot;">​</a></h3><p>选择如图所示：</p><h3 id="选择要安装win11系统到哪里" tabindex="-1"><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151511176198131189700.jpg" alt=""> 选择要安装win11系统到哪里 <a class="header-anchor" href="#选择要安装win11系统到哪里" aria-label="Permalink to &quot;![](https://www.softbangong.com/wp-content/uploads/2026/04/20251101151511176198131189700.jpg) 选择要安装win11系统到哪里&quot;">​</a></h3><p>这里，如果是安装到一个新的硬盘，则直接选择即可</p><p>——————————————</p><p>如果需要对硬盘进行分区，点击新建，按照硬盘大小进行分配即可</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151625176198138599033.jpg" alt=""></p><h3 id="之后会进入到系统自动安装界面" tabindex="-1">之后会进入到系统自动安装界面 <a class="header-anchor" href="#之后会进入到系统自动安装界面" aria-label="Permalink to &quot;之后会进入到系统自动安装界面&quot;">​</a></h3><p>这部分走完后，系统会重启，进入到系统配置界面</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151828176198150885371.jpg" alt=""></p><h3 id="进入系统配置界面" tabindex="-1">进入系统配置界面 <a class="header-anchor" href="#进入系统配置界面" aria-label="Permalink to &quot;进入系统配置界面&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101151955176198159511981.jpg" alt=""></p><h3 id="" tabindex="-1"><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152020176198162039015.jpg" alt=""> <img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152048176198164833897.jpg" alt=""> <a class="header-anchor" href="#" aria-label="Permalink to &quot;![](https://www.softbangong.com/wp-content/uploads/2026/04/20251101152020176198162039015.jpg) ![](https://www.softbangong.com/wp-content/uploads/2026/04/20251101152048176198164833897.jpg)&quot;">​</a></h3><p><strong>设置相关名称</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152109176198166914650.jpg" alt=""></p><p><strong>进行相关安全设置</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152156176198171625913.jpg" alt=""></p><h3 id="全部选择否" tabindex="-1">全部选择否 <a class="header-anchor" href="#全部选择否" aria-label="Permalink to &quot;全部选择否&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152223176198174371255.jpg" alt=""></p><h3 id="进入系统" tabindex="-1">进入系统 <a class="header-anchor" href="#进入系统" aria-label="Permalink to &quot;进入系统&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152309176198178973042.png" alt=""></p><h3 id="进入系统后-激活win11-然后在能在个性化里的主题部分-桌面图片添加到桌面" tabindex="-1">进入系统后，激活win11,然后在能在个性化里的主题部分，桌面图片添加到桌面 <a class="header-anchor" href="#进入系统后-激活win11-然后在能在个性化里的主题部分-桌面图片添加到桌面" aria-label="Permalink to &quot;进入系统后，激活win11,然后在能在个性化里的主题部分，桌面图片添加到桌面&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251101152431176198187131921.jpg" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2130.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2130.html</a></p>',58)])])}const d=o(s,[["render",e]]);export{h as __pageData,d as default};
